# CLAUDE_PROJECT_DIR is explicitly set to the fixture dir ($1) in all three
# helpers below -- session-start.sh/session-end.sh prefer CLAUDE_PROJECT_DIR
# over git-toplevel, so merely `cd`ing into the fixture and relying on
# git-toplevel would let any ambient CLAUDE_PROJECT_DIR already set in the
# environment running this suite (exactly what happens under a real Claude
# Code hook invocation, e.g. verify-task-quality.sh's own TaskCompleted run)
# leak through and point these hooks at the real repo instead of the
# isolated fixture.
run_session_start() {
  (cd "$1" && printf '%s' "$2" | CLAUDE_PROJECT_DIR="$1" env -u CLAUDE_PLUGIN_ROOT -u HERDR_ENV -u HERDR_WORKSPACE_ID bash "$HOOKS_DIR/session-start.sh")
}

run_session_start_with_root() {
  (cd "$1" && printf '%s' "$2" | CLAUDE_PROJECT_DIR="$1" CLAUDE_PLUGIN_ROOT="$3" env -u HERDR_ENV -u HERDR_WORKSPACE_ID bash "$HOOKS_DIR/session-start.sh")
}

run_session_end() {
  (cd "$1" && CLAUDE_PROJECT_DIR="$1" bash "$HOOKS_DIR/session-end.sh" </dev/null)
}

run_statusline() {
  printf '%s' "$1" | bash "$HOOKS_DIR/statusline.sh"
}

